<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;class Customer extends Model{protected $fillable=['branch_id','name','phone','email','birth_date','notes','active'];protected function casts():array{return['birth_date'=>'date','active'=>'boolean'];}public function addresses(){return $this->hasMany(CustomerAddress::class);}public function orders(){return $this->hasMany(Order::class);}public function loyaltyTransactions(){return $this->hasMany(LoyaltyTransaction::class);}public function getPointsBalanceAttribute():float{return(float)$this->loyaltyTransactions()->sum('points');}}
